/** Display names, matching the Figma master names. */
export const PLATFORM_NAMES: Record<Platform, string> = {
  insights: 'EDGE Insights',
  knowledge: 'EDGE Knowledge',
  connections: 'EDGE Connections',
  certifications: 'EDGE Certifications',
  compliance: 'EDGE Compliance',
  payTool: 'EDGE Pay Tool',
};

export function PlatformLogo({ platform, size = 24, title, ...svgProps }: PlatformLogoProps) {
  const brand = colors.platforms[platform];
  const glyph = colors.platforms.glyph;
  const { glyph: glyphPaths, cutout = [] } = GLYPHS[platform];
  const a11y = title
    ? { role: 'img' as const, 'aria-label': title }
    : { 'aria-hidden': true as const, focusable: 'false' as const };

  return (
    <svg width={size} height={size} viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg" {...a11y} {...svgProps}>
      <path d={CIRCLE} fill={brand} />
      {glyphPaths.map((d, i) => (
        <path key={`g${i}`} d={d} fill={glyph} />
      ))}
      {cutout.map((d, i) => (
        <path key={`c${i}`} d={d} fill={brand} />
      ))}
      {platform === 'payTool' &&
        PAY_TOOL_TOP.map((d, i) => <path key={`t${i}`} d={d} fill={glyph} />)}
    </svg>
  );
}

export default PlatformLogo;
